"""Citations littérales extraites des informations professionnelles locales lues."""
import gzip,re
from html import escape
from format_lecon import R,paras
NUM={16:'29349',17:'53116',18:'59876',19:'45674',20:'56551',25:'58178'}
def source(n):return gzip.open(R/f'ressources_ia/aips/fi_fr/{NUM[n]}.txt.gz','rt').read()
def quote(s):return '<blockquote><p>« '+escape(s.strip())+' »</p></blockquote>'
def line(n,start):
 found=[x for x in source(n).splitlines() if x.startswith(start)]
 assert len(found)==1,(n,start,len(found))
 return quote(found[0])
def segment(n,start,end):
 s=source(n);a=s.index(start)+len(start);b=s.index(end,a)
 return quote(s[a:b])
def window(l,n):
 if n==16:
  title='Prednisone : limites et sécurité suisse'
  body=paras('La prednisone est proposée dans le protocole HUG pour Bell, mais cette indication et sa posologie spécifique ne figurent pas dans l’information professionnelle Prednisone Streuli 29349. Il s’agit donc ici d’un usage hors indication. Les schémas institutionnels et européens ne sont pas présentés comme des posologies AIPS ; la prescription doit être individualisée par le médecin.', 'L’absence de schéma AIPS spécifique n’annule pas les données d’efficacité des corticoïdes précoces dans Bell. Elle empêche de fabriquer une prescription réglementaire ou pédiatrique à partir d’une autre maladie.', 'Contre-indications et portée de la rubrique, citation AIPS :')+segment(16,'\nContre-indications\n','\nMises en garde')+paras('Grossesse et allaitement, citation AIPS :')+segment(16,'\nGrossesse, allaitement\n','\nEffet sur')+paras('Vérifier notamment diabète, infection, risque oculaire, antécédents psychiatriques et traitements associés. L’indication et le suivi de la glycémie sont adaptés au terrain. Une neuroborréliose probable ou confirmée ne relève pas d’une transposition automatique du traitement de Bell.')
  refs=(1,12,13,16)
 elif n==17:
  title='Valtrex : zona, adaptation rénale et précautions'
  body=paras('Valtrex contient du valaciclovir. La posologie citée concerne le zona de l’adulte ; elle ne doit pas être confondue avec celle d’une autre infection herpétique ni avec un traitement systématique de Bell.', 'Indication et délai selon AIPS :')+line(17,'Valtrex est indiqué pour le traitement du zona')+paras('Dose pour le zona, citation AIPS :')+line(17,'1000 mg de Valtrex 3 fois par jour pendant 7 jours.')+paras('Voie orale ; vérifier fonction rénale et hydratation. Adaptation au zona, tableau AIPS cité dans son ordre :')+segment(17,'Traitement du zona (zona ophtalmique inclus):\n','\nTraitement de l\'herpès:')+line(17,'Chez les patients traités par hémodialyse intermittente')+paras('Contre-indication, citation AIPS :')+line(17,"L'usage de Valtrex est contre-indiqué")+paras('Enfant, grossesse et allaitement, citations AIPS :')+line(17,"Comme il n'existe pas encore de données à ce propos")+line(17,'Valtrex ne doit pas être utilisé pendant la grossesse')+line(17,"La prudence s'impose lorsque Valtrex")+paras('Ne pas appliquer le schéma adulte à l’enfant. Le sujet âgé peut nécessiter une adaptation rénale ; une accumulation expose notamment à des effets neurologiques. Une atteinte neurologique étendue ou une immunodépression peut demander une stratégie hospitalière différente de ce schéma oral.')
  refs=(1,17)
 elif n==18:
  title='Ceftriaxon Labatec : Lyme et précautions'
  body=paras('La ceftriaxone est une option de traitement de la neuroborréliose, parmi d’autres antibiotiques recommandés. La voie, le terrain et le tableau clinique guident le choix spécialisé. La fiche suisse inclut la maladie de Lyme disséminée.', 'Posologie spécifique Lyme, citation AIPS :')+line(18,'La posologie en cas de maladie de Lyme est de')+paras('La durée de quatorze jours correspond à la fiche de ce produit et à la recommandation européenne pour la forme précoce. Les formes tardives ou complexes demandent une décision spécialisée ; ne pas prolonger automatiquement devant des symptômes résiduels.', 'Contre-indications, dont situations néonatales, citation AIPS :')+segment(18,'\nContre-indications\n','\nMises en garde')+paras('Grossesse et allaitement, citation AIPS :')+segment(18,'\nGrossesse, allaitement\n','\nEffet sur')+paras('Pour le traitement intraveineux, suivre les instructions de reconstitution et de perfusion du produit. Les solutions contenant de la lidocaïne sont destinées à l’injection intramusculaire et ne sont pas utilisées par voie intraveineuse. Vérifier les incompatibilités avec le calcium et les autres produits ; une atteinte rénale et hépatique combinée impose une appréciation spécialisée.')
  refs=(13,18)
 elif n==19:
  title='Augmentin oral : cadre et précautions'
  body=paras('Cette option orale concerne un patient sélectionné, stable, pouvant avaler et bénéficiant du traitement de la source infectieuse. Elle n’est pas un schéma de prise en charge d’une cellulite profonde menaçant les voies aériennes. Le choix antibiotique dépend des recommandations locales et du terrain.', 'Dose usuelle des comprimés pour adultes et enfants de plus de quarante kilogrammes, citation AIPS :')+line(19,'Pour les infections légères, modérées et sévères')+paras('Le nombre total désigne la combinaison amoxicilline/acide clavulanique. Ne pas mélanger les proportions entre présentations. Adaptations rénales, citation AIPS :')+segment(19,'Adultes et enfants de plus de 40 kg:\n','\nHémodialyse')+line(19,'Il est recommandé de prendre Augmentin au début des repas')+paras('La durée d’une cellulite odontogène n’est pas fixée par cette rubrique AIPS ; elle est définie par la gravité, le drainage, l’évolution et le protocole de l’équipe. Ne pas laisser une antibiothérapie remplacer le contrôle du foyer dentaire.', 'Enfants, citation AIPS :')+line(19,'Augmentin comprimés filmés ne convient pas')+paras('Contre-indications, citation AIPS :')+segment(19,'\nContre-indications\n','\nMises en garde')+paras('Grossesse et allaitement, citations AIPS :')+line(19,'Augmentin ne devrait donc être utilisé pendant la grossesse')+line(19,'Il ne faudrait donc pas allaiter pendant le traitement')+paras('Rechercher allergie aux bêta-lactamines, antécédent hépatique lié au produit, fonction rénale et interactions. Une réaction allergique, une atteinte cutanée sévère ou une diarrhée importante impose une réévaluation. Une alternative en cas d’allergie doit être choisie avec l’équipe selon le contexte, sans substitution empirique universelle.')
  refs=(7,19)
 elif n==20:
  title='Adrénaline intramusculaire : anaphylaxie'
  # Les apostrophes du texte officiel sont conservées exactement.
  s=source(20);start='Les doses chez l\'enfant et l’adolescent sont:';a=s.index(start);b=s.index('\nEn injection intraveineuse',a)
  body=paras('L’adrénaline intramusculaire est le traitement initial d’une anaphylaxie menaçante, avec appel urgent, surveillance et soutien des fonctions vitales. La stratégie d’un angioœdème bradykinique est différente ; aucun antihistaminique ne remplace la sécurisation respiratoire.', 'Adrenalin Sintetica à un milligramme par millilitre, rubrique choc anaphylactique :')+quote('La dose habituelle est de 500 microgrammes')+paras('Cela correspond à un demi-millilitre de cette solution. Répétition, citation AIPS :')+quote('Si nécessaire, cette dose peut être répétée plusieurs fois à des intervalles de 5 minutes en fonction de la pression artérielle, le pouls et la fonction respiratoire.')+paras('Injection intramusculaire dans la face antérolatérale de la cuisse. Ne pas injecter directement par voie intraveineuse la solution à un milligramme par millilitre dans cette indication ; cette voie et ses dilutions relèvent d’une équipe expérimentée.', 'Tableau pédiatrique AIPS de la rubrique intramusculaire, dans l’ordre âge/dose :')+quote(s[a:b])+paras('La fiche comporte des contre-indications systémiques et précise leur portée en urgence vitale. Citation déterminante pour éviter de retarder un traitement salvateur :')+line(20,'L’utilisation d’adrénaline pour un traitement systémique')+paras('Grossesse, citation AIPS :')+quote("De ce fait l'adrénaline ne devrait être administrée pendant la grossesse que si c'est clairement indispensable .")+paras('Une anaphylaxie menaçante est une urgence maternelle ; ne pas retarder la prise en charge. Le produit passe dans le lait maternel ; la conduite d’allaitement et la surveillance sont discutées après sécurisation. La fiche signale notamment interactions avec bêta-bloquants et antidépresseurs tricycliques : informer l’équipe et surveiller la réponse.')
  body+=paras('Contre-indications systémiques et exception vitale, citation AIPS :')+segment(20,'\nContre-indications\n','\nAdrenalin Sintetica ne doit pas être utilisée en complément')+paras('Allaitement, citation AIPS :')+segment(20,'\nAllaitement\n','\nEffet sur')
  refs=(8,15,20)
 elif n==25:
  title='Firazyr : indication héréditaire et limites'
  body=paras('L’icatibant de Firazyr est un traitement spécifique de certaines crises héréditaires. Cette information ne couvre pas tous les angioœdèmes bradykiniques ; son usage dans une réaction à un IEC n’est pas inclus dans l’indication citée et ne doit pas être transposé automatiquement.', 'Indication et dose adulte, citations AIPS :')+line(25,'Firazyr est indiqué dans le traitement symptomatique')+line(25,'La dose recommandée chez les adultes')+line(25,'Dans la majorité des cas, une seule injection')+paras('Injection sous-cutanée lente, de préférence abdominale. Les doses supplémentaires nécessaires chez l’adulte sont administrées dans un établissement médical ; un œdème laryngé impose une observation médicale même après traitement à domicile.', 'Limites pédiatriques, citations AIPS :')+line(25,"Dans l'étude clinique, il n'a pas été administré plus")+line(25,'Aucune posologie ne peut être recommandée')+paras('Pour les enfants admissibles, le tableau pondéral AIPS est cité ci-dessous ; le schéma de répétition adulte ne leur est pas appliqué.')+segment(25,'Tableau 1:',"Dans l'étude clinique, il n'a pas été administré plus")+paras('Contre-indication, citation AIPS :')+line(25,"Hypersensibilité au principe actif ou à l'un des excipients.")+paras('Grossesse et allaitement, citations AIPS :')+line(25,'Firazyr ne doit être utilisé pendant la grossesse')+line(25,"On ne sait pas si l'icatibant est excrété")+paras('La fiche ne demande pas d’adaptation rénale ou hépatique. Elle recommande la prudence en cas de cardiopathie ischémique aiguë, d’angine instable ou dans les semaines suivant un AVC. Première administration sous supervision, formation préalable pour l’auto-administration ou le proche et recours médical en cas de réponse insuffisante. La sécurisation des voies aériennes reste prioritaire.')
  refs=(8,25)
 else:raise ValueError(n)
 return l.subwindow('med'+str(n),title,body,refs)
